// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  GatewayRow.swift
//  Latchkey
//
//  F22: the app bar's row of gateways. One chip per remembered gateway, the
//  one in use first, each with the dashboard's instance-bar light; one tap
//  on another switches to it directly. The dashboard's own instance bar
//  cannot do this from a phone: its remotes are plain-HTTP frames on the
//  gateway's loopback (F5 §5). These are gateways the app itself opens.
//
//  It lives in the bar, so it is there only when the bar is (F15): nothing
//  of it is on the page, and it adds no height.
//

import SwiftUI

struct GatewayRow: View {
    /// In order, in use first (`GatewayChipState.order`); never empty.
    let origins: [String]
    let current: String
    /// The page in use: its load is the in-use chip's light.
    @ObservedObject var page: BrowserViewModel
    /// The node: whether it has a rule set yet, and which hosts it carries.
    @ObservedObject var tsnet: TSNetModel
    @ObservedObject var health: GatewayHealth
    let onSwitch: (String) -> Void

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 4) {
                ForEach(origins, id: \.self) { origin in
                    GatewayChip(origin: origin, inUse: origin == current, state: state(origin)) {
                        onSwitch(origin)
                    }
                }
            }
            .padding(.horizontal, 2)
        }
        .scrollBounceBehavior(.basedOnSize, axes: .horizontal)
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("gateway-row")
        // Probes only while the row is on screen, and again every
        // `freshFor` while it stays (F22 §4). Started again when the tailnet
        // becomes ready: the row is often up before the node is, and a
        // refresh then can probe nothing.
        .task(id: Probing(origins: others, ready: ready)) {
            while !Task.isCancelled {
                health.refresh(others)
                try? await Task.sleep(for: GatewayHealth.freshFor)
            }
        }
        .onDisappear { health.stop() }
    }

    private var others: [String] { origins.filter { $0 != current } }

    private var ready: Bool {
        tsnet.proxyConfiguration != nil && tsnet.proxyPolicy?.hasPeerData == true
    }

    private struct Probing: Equatable {
        let origins: [String]
        let ready: Bool
    }

    private func state(_ origin: String) -> GatewayChipState {
        if origin == current { return .current(Self.load(page.pageState)) }
        let host = URL(string: origin)?.host() ?? ""
        let policy = tsnet.proxyPolicy
        return .other(ready: policy?.hasPeerData == true,
                      carried: !host.isEmpty && policy?.matchingRule(for: host) != nil,
                      verdict: health.verdicts[origin])
    }

    static func load(_ state: PageState) -> GatewayChipState.Load {
        switch state {
        case .idle: return .idle
        case .holding, .connecting: return .connecting
        case .committed: return .committed
        case .failed: return .failed
        }
    }
}

/// One chip: the dashboard's `e8`, in SwiftUI. A bordered 26 pt capsule-ish
/// button, 12 pt text and a 6 pt light; the one in use filled and bold.
private struct GatewayChip: View {
    let origin: String
    let inUse: Bool
    let state: GatewayChipState
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            HStack(spacing: 5) {
                Circle()
                    .fill(Self.color(state.light))
                    .frame(width: 6, height: 6)
                Text(GatewayChipState.shortName(origin))
                    .font(.system(size: 12, weight: inUse ? .bold : .regular))
                    .lineLimit(1)
                    .truncationMode(.tail)
                    .frame(maxWidth: 140, alignment: .leading)
                    .fixedSize(horizontal: true, vertical: false)
                if !state.word.isEmpty && state.light != .ok {
                    Text(state.word)
                        .font(.system(size: 11))
                        .foregroundStyle(state.light == .muted ? Color.secondary : Self.color(state.light))
                        .lineLimit(1)
                        .fixedSize()
                }
            }
            .foregroundStyle(inUse ? Color.accentColor : Color.primary)
            .padding(.horizontal, 8)
            .frame(height: 26)
            .background {
                RoundedRectangle(cornerRadius: 6)
                    .fill(inUse ? Color.accentColor.opacity(0.15) : Color.clear)
            }
            .overlay {
                if !inUse {
                    RoundedRectangle(cornerRadius: 6)
                        .strokeBorder(Color.secondary.opacity(0.35), lineWidth: 1)
                }
            }
            .background(.thinMaterial, in: RoundedRectangle(cornerRadius: 6))
            .frame(minHeight: 44)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        // The chip in use is not a switch, and a gateway off the tailnet may
        // not be chosen at all; the dimmed look is the not-enabled trait.
        .disabled(!state.tappable)
        .opacity(!state.tappable && !inUse ? 0.6 : 1)
        .accessibilityLabel(GatewayChipState.shown(origin) + (inUse ? ", in use" : ""))
        .accessibilityValue(state.word)
        .accessibilityIdentifier("gateway-chip-\(GatewayChipState.shown(origin))")
    }

    /// KiroCrew's `--ok`, `--warn`, `--danger` and `--muted`, as the system's
    /// own green, orange, red and grey, which adapt to light and dark.
    static func color(_ light: GatewayChipState.Light) -> Color {
        switch light {
        case .ok: return .green
        case .warn: return .orange
        case .danger: return .red
        case .muted: return .gray
        }
    }
}

// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  GatewayChipState.swift
//  Latchkey
//
//  F22: what one chip in the app bar's gateway row says. Pure, so the table
//  in F22 §4 is tested on the host (scripts/test-gateway-row.sh).
//
//  The lights are the dashboard's own (its instance bar colours `connected`
//  --ok, `connecting` --warn, `error` --danger, anything else --muted), and
//  mean the same things: the chip in use follows its page's load, the others
//  a probe of their own gateway. As there, a chip that is not green says its
//  state in words, so colour is never the only signal.
//

import Foundation

nonisolated struct GatewayChipState: Equatable, Sendable {
    enum Light: Equatable, Sendable { case ok, warn, danger, muted }

    /// The page's load, for the chip in use: `PageState` folded to what the
    /// light shows.
    enum Load: Equatable, Sendable { case idle, connecting, committed, failed }

    /// A probe of another gateway (`GatewayHealth`).
    enum Verdict: Equatable, Sendable { case checking, answering, notGateway, notAnswering }

    let light: Light
    /// "" when the light says it all: the dashboard shows no word for green.
    let word: String
    /// The chip in use is never a switch; a gateway the tailnet cannot reach
    /// is not either (it would load direct, off the tailnet: F5 §7).
    let tappable: Bool

    static func current(_ load: Load) -> Self {
        switch load {
        case .committed: return .init(light: .ok, word: "connected", tappable: false)
        case .connecting: return .init(light: .warn, word: "connecting", tappable: false)
        case .failed: return .init(light: .danger, word: "failed", tappable: false)
        case .idle: return .init(light: .muted, word: "", tappable: false)
        }
    }

    /// Another gateway. `verdict` nil means not probed yet: it is about to
    /// be, as the row only exists while it is probing.
    static func other(ready: Bool, carried: Bool, verdict: Verdict?) -> Self {
        guard ready else { return .init(light: .muted, word: "tailnet not connected", tappable: false) }
        guard carried else { return .init(light: .muted, word: "not on this tailnet", tappable: false) }
        switch verdict {
        case .answering: return .init(light: .ok, word: "answering", tappable: true)
        case .checking, nil: return .init(light: .warn, word: "checking", tappable: true)
        case .notGateway: return .init(light: .danger, word: "not KiroCrew", tappable: true)
        case .notAnswering: return .init(light: .danger, word: "not answering", tappable: true)
        }
    }

    /// `host` or `host:port` without the scheme: the chip's identifier and
    /// its accessibility label, as Settings' rows name a gateway.
    static func shown(_ origin: String) -> String {
        origin.replacingOccurrences(of: "https://", with: "")
    }

    /// The chip's text: the first DNS label, and the port off 443.
    /// `https://mac-studio.tail1234.ts.net:8443` → `mac-studio:8443`.
    static func shortName(_ origin: String) -> String {
        guard let parts = URLComponents(string: origin), let host = parts.host, !host.isEmpty
        else { return shown(origin) }
        let label = host.split(separator: ".").first.map(String.init) ?? host
        if let port = parts.port, port != 443 { return "\(label):\(port)" }
        return label
    }

    /// The row's chips, in order: the one in use, then the others as the
    /// remembered list has them (most recent first), each once. Empty when
    /// there is nothing to switch to: one chip alone is no row (F22 §2).
    static func order(current: String, known: [String]) -> [String] {
        var seen: Set<String> = [current]
        let others = known.filter { seen.insert($0).inserted }
        guard !current.isEmpty, !others.isEmpty else { return [] }
        return [current] + others
    }
}

// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  AppBar.swift
//  Latchkey
//
//  The one strip of the screen Latchkey owns while the dashboard is up (F15).
//
//  Latchkey may not assume it owns any part of the screen the page is using:
//  the dashboard draws its own controls in its corners, and the gear used to
//  sit on top of its notification bell. So the app's controls live in a bar
//  ABOVE the page, and the page starts where the bar ends. It is not an
//  overlay: an overlaying bar relies on the page insetting itself, and F9
//  measured this gateway ignoring the inset outside an installed web app.
//
//  The bar is absent in the steady state. A deliberate scroll up brings it
//  in and one down takes it away, Safari's model; a page that cannot scroll
//  always has it. `AppBarRetraction` is the policy and `AppBarController`
//  the reasons it must be on screen. Every change resizes the web view,
//  which is why the policy is strict and why Reduce Motion gets no
//  animation at all.
//

import SwiftUI

/// The bar above the page, then everything below it. The whole column's
/// layout animates together when the bar moves, so the page's top edge
/// follows the bar's bottom edge rather than jumping ahead of it.
struct AppBarColumn<Content: View>: View {
    @ObservedObject var model: BrowserViewModel
    @ObservedObject var controller: AppBarController
    let showsSignIn: Bool
    /// Keep the bar on screen for a reason other than sign-in: the gateway
    /// refusing this origin (F1 §4a) leaves the page inert, and the gear is
    /// then the owner's only way out.
    var pinnedForTrouble = false
    /// F22: the gateway row, for the bar's middle, or nil when there is no
    /// other gateway to show.
    var gatewayRow: AnyView? = nil
    let onSignIn: () -> Void
    let onSettings: () -> Void
    @ViewBuilder let content: Content

    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        VStack(spacing: 0) {
            AppBar(model: model, retracted: controller.retracted, showsSignIn: showsSignIn,
                   gatewayRow: gatewayRow, onSignIn: onSignIn, onSettings: onSettings)
            content
        }
        // The page's own canvas colour behind the bar and the status-bar strip
        // above it (F9 §0.1), so bar, strip and page read as one surface. A
        // view background does not reach into the safe area by itself.
        .background { PageTint(model: model).ignoresSafeArea() }
        // F21: what that colour was, report by report (test builds, on request).
        .pageBackgroundInstrument(model)
        .animation(AppBar.animation(reduceMotion: reduceMotion), value: controller.retracted)
        // The sign-in button must not be scrolled away: it is the only one.
        .onChange(of: showsSignIn || pinnedForTrouble, initial: true) { _, pinned in
            controller.setPinned(pinned)
        }
    }
}

struct AppBar: View {
    @ObservedObject var model: BrowserViewModel
    let retracted: Bool
    let showsSignIn: Bool
    var gatewayRow: AnyView? = nil
    let onSignIn: () -> Void
    let onSettings: () -> Void

    /// Reduce Motion: the bar and the page move in one step, not a slide.
    static func animation(reduceMotion: Bool) -> Animation? {
        reduceMotion ? nil : .easeOut(duration: 0.2)
    }

    var body: some View {
        // Retracted, the controls are REMOVED, not merely clipped away. A
        // zero-height clipped bar still lays its controls out, above itself,
        // under the status bar: invisible, and still hittable by accessibility
        // (L1 caught exactly that gear on the first run). An element that is
        // there and cannot be seen is the failure F15 §4b forbids. VoiceOver
        // and Switch Control never see this state at all (`AppBarController`).
        ZStack(alignment: .bottom) {
            if !retracted {
                HStack(spacing: 8) {
                    ReturnToDashboardAffordance(model: model)
                    if let gatewayRow {
                        // F22: the sign-in capsule is sized first, as the
                        // only way in (F15 §9); the row scrolls in what is
                        // left. Signed out is when a way to another gateway
                        // matters most, so neither hides the other. Not
                        // fixedSize: at the largest text the capsule alone
                        // is wider than the screen, and pushed the gear off.
                        if showsSignIn { signIn.layoutPriority(1) }
                        gatewayRow
                            .frame(maxWidth: .infinity, alignment: .leading)
                    } else {
                        Spacer(minLength: 0)
                        if showsSignIn { signIn }
                        Spacer(minLength: 0)
                    }
                    settings
                }
                .padding(.horizontal, 6)
                .frame(height: CGFloat(AppBarRetraction.barHeight))
            }
        }
        .frame(maxWidth: .infinity)
        // Zero height when retracted: the column closes over it and the web
        // view starts at the safe-area top.
        .frame(height: retracted ? 0 : CGFloat(AppBarRetraction.barHeight), alignment: .bottom)
        .clipped()
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("app-bar")
    }

    /// Settings, and through it the log viewer and the routing diagnostic:
    /// the reason the dashboard needs any chrome at all (PLAN §1.9).
    ///
    /// Full opacity. Over the page it used to be faded, and over a web view a
    /// button below full opacity gets no taps at all (M1–R29); in the bar it
    /// is not over anything. The material disc keeps it legible on whatever
    /// colour the page's canvas is.
    private var settings: some View {
        Button(action: onSettings) {
            Image(systemName: "gearshape.fill")
                .font(.system(size: 15, weight: .semibold))
                .foregroundStyle(.secondary)
                .padding(7)
                .background(.thinMaterial, in: Circle())
                .frame(width: 44, height: 44)
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityIdentifier("settings-button")
        .accessibilityLabel("Settings")
    }

    /// The way back to the sign-in sheet after closing it: the page's own
    /// banner is hidden (R22), so this is the only sign-in control.
    private var signIn: some View {
        Button(action: onSignIn) {
            Label("Signed out — Sign in", systemImage: "person.crop.circle.badge.exclamationmark")
                .font(.subheadline.weight(.semibold))
                .lineLimit(1)
                .minimumScaleFactor(0.8)
                .padding(.horizontal, 14)
                .padding(.vertical, 8)
                .background(.thinMaterial, in: Capsule())
        }
        .buttonStyle(.plain)
        .accessibilityIdentifier("session-signin-button")
    }
}

/// The page's canvas colour, or the system background until it reports one
/// and on the app's own state pages (F9 §0.1).
private struct PageTint: View {
    @ObservedObject var model: BrowserViewModel

    var body: some View {
        guard model.pageState == .committed,
              let rgb = PageScriptSources.opaqueRGB(fromCSS: model.pageBackgroundCSS)
        else { return Color.platformSystemBackground }
        return Color(.sRGB, red: rgb.red, green: rgb.green, blue: rgb.blue)
    }
}

